head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "JLDSTF11100";
scwin.grd_Grid = null;
scwin.panel_page = null;
scwin.gAcptNo = undefined;
scwin.gViewerStat = "P";
scwin.gIsurCd = undefined;
scwin.gExmptYn = undefined;
scwin.gDate = undefined;
scwin.search_yn = false;
scwin.dts_DsclApprovalList = null;
scwin.dts_emp = null;
scwin.dts_dep = null;
scwin.dts_ApprovalCond = null;
scwin.dts_DutyStatus = null;
scwin.gDepCd = undefined;
scwin.gEmpNo = undefined;
scwin.gLdMktTp = undefined;
scwin.gDutyYn = undefined;
scwin.gDutyChrg = undefined;
scwin.gJobTitle = undefined;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name init_attrReals
 * @description 속성 실현 — as-is EL 이 그리던 안내 문구·속성을 컨텍스트 값으로 반영(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_attrReals = function () {
    const attrRealsList = [{ childId: "chk_chbStatAll", attr: "__value", fn: function () { return "1"; } },
        { childId: "chk_chbAffstatAll", attr: "__value", fn: function () { return "1"; } }];
    attrRealsList.forEach(function (a) {
        const comp = $c.util.getComponent(a.childId);
        if (!comp) { return; }
        let v;
        try { v = a.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "attrReal:" + a.childId }); return; }
        if (a.attr === "style") {
            String(v).split(";").forEach(function (decl) {
                const kv = decl.split(":");
                if (kv.length === 2 && kv[0].trim()) { comp.setStyle(kv[0].trim(), kv[1].trim()); }
            });
        } else if (a.attr === "label" || a.attr === "__value") {
            if (typeof comp.setValue === "function") { comp.setValue(v); } else if (comp.render) { comp.render.textContent = v; }
        } else if (a.attr === "__items") {
            if (typeof comp.addItem === "function" && v && v.length) {
                if (typeof comp.removeAll === "function") { comp.removeAll(); }
                v.forEach(function (it) { comp.addItem(String(it[0] || ""), String(it[1] || "")); });
            }
        } else if (a.attr === "class") {
            if (comp.render) { comp.render.className = v; }
        } else if (a.attr === "__html") {
            if (comp.render) { comp.render.innerHTML = v; }
        } else if (comp.render) {
            comp.render.setAttribute(a.attr, v);
        }
    });
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_pageBody = async function () {
    try {
        await scwin.tx_script_dts_dep();

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf11100.onpageload' }); }
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

try { scwin.gDepCd =$c.session.getUserInfo("depCd"); } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldstf11100' }); }

try { scwin.gEmpNo =$c.session.getUserInfo("empNo"); } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldstf11100' }); }

try { scwin.gLdMktTp =$c.session.getUserInfo("market"); } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldstf11100' }); }

try { scwin.gDutyYn =js_duty; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldstf11100' }); }

try { scwin.gDutyChrg =js_duty_chrg; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldstf11100' }); }

try { scwin.gJobTitle =js_jobtitl; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldstf11100' }); }

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.grd_Grid = $c.util.getComponent('grd_Grid');
        scwin.panel_page = $c.util.getComponent('panel_page');
        scwin.dts_DsclApprovalList = typeof __krxRowShim === 'function' ? __krxRowShim($c.util.getComponent('dts_DsclApprovalList')) : $c.util.getComponent('dts_DsclApprovalList');
        scwin.dts_emp = typeof __krxRowShim === 'function' ? __krxRowShim($c.util.getComponent('dtsEmp')) : $c.util.getComponent('dtsEmp');
        scwin.dts_dep = typeof __krxRowShim === 'function' ? __krxRowShim($c.util.getComponent('dtsDep')) : $c.util.getComponent('dtsDep');
        scwin.dts_ApprovalCond = typeof __krxRowShim === 'function' ? __krxRowShim($c.util.getComponent('dts_ApprovalCond')) : $c.util.getComponent('dts_ApprovalCond');
        scwin.dts_DutyStatus = typeof __krxRowShim === 'function' ? __krxRowShim($c.util.getComponent('dts_DutyStatus')) : $c.util.getComponent('dts_DutyStatus');
        scwin.init_attrReals();
        await scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldstf11100.onpageload' });
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name grd_Grid_ondblclick
 * @description grd_Grid 더블클릭 이벤트
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.grd_Grid_ondblclick = function (row, colid) {
    // TODO Stage2: 공급사 pcc 의존(저장소 pcc/fil 에 없음 · 반입 또는 치환 판단) — $c.fil.fn_OpenDisclAllList, $c.fil.fn_OpenNoDisclViewer, $c.fil.fn_PopupCorpInfo
    try {
        scwin.setContnId(row);
        if (scwin.gExmptYn === 'Y') {
            scwin.gViewerStat = 'A';
        } else {
            scwin.gViewerStat = 'P';
        }
        if (colid === "DOC_TITLE") {
            $c.fil.fn_OpenNoDisclViewer(scwin.gAcptNo, scwin.gViewerStat, $c.session.getUserInfo("empNo"), $c.session.getUserInfo("depCd"), js_jobtitl, js_duty, js_duty_chrg, 'M', scwin.dts_DutyStatus);
        } else {
            if (colid === "ACPT_DDTM") {
                $c.fil.fn_OpenDisclAllList();
            } else {
                if (colid === "COM_ABBRV") {
                    $c.fil.fn_PopupCorpInfo();
                }
            }
        }

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf11100.grd_Grid_ondblclick' }); }
};

