    // setObjectValue(cmb_EmpList, js_emp_no) ;    // 로그인사람을 디폴트 선택시

};

/**
 * @method
 * @name cmb_TeamList_onselchange
 * @description cmb_TeamList onselchange 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.cmb_TeamList_onselchange = function () {
    try {
        scwin.gDepCd = slc_cmb_TeamList.valueOfIndex("VALUE", slc_cmb_TeamList.Index);
        if (scwin.gDepCd === '') {
            slc_cmb_EmpList.setValue('');
        }
        scwin.dts_emp.UseFilter = true;
        scwin.dts_emp.setColumnFilter();
        scwin.dts_emp.SortExpr = "DEP_CD";
        scwin.dts_emp.sort();

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf11100.cmb_TeamList_onselchange' }); }
};

/**
 * @method
 * @name dts_emp_onfilter
 * @description dts_emp onfilter 이벤트
 * @param {Number} row 행 인덱스
 * @returns {void}
 * @hidden N
 */
scwin.dts_emp_onfilter = function (row) {
    try {
        if (scwin.gDepCd === "") {
            return true;
        } else {
            if (scwin.dts_emp.getCellData(row, "depCd") === scwin.gDepCd || scwin.dts_emp.getCellData(row, "depCd") === "") {
                return true;
            } else {
                return false;
            }
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "jldstf11100.dts_emp_onfilter" });
    }
};

