scwin.dts_DsclApprovalList_onloadcompleted = async function (rowcount) {
    try {
        if (scwin.dts_DsclApprovalList.errorMsg) {
            await $c.win.alert(scwin.dts_DsclApprovalList.errorMsg);
        } else {
            $c.fil.showTotalCount(rowcount, scwin.panel_page);
        }
        void 0;
        scwin.search_yn = false;
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "jldstf11100.dts_DsclApprovalList_onloadcompleted" });
    }
};

