};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_script_dts_dep
 * @description script dts dep 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_script_dts_dep = async function () {
    $c.util.getComponent("dma_scriptDtsDepReq").set("inputMessageId", "CODE_EMPDEP_IN");
    $c.util.getComponent("dma_scriptDtsDepReq").set("outputMessageId", "CODE_EMPDEP_OUT");
    $c.util.getComponent("dma_scriptDtsDepReq").set("For", "R");
    // as-is 가 URL 에 싣던 값을 정적으로 못 읽었다 — 빈 파라미터로 보내지 않는다.
    // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "보낼 입력값을 아직 읽지 못합니다(전환 미완) — DEP_CD"
    throw { bizMessage: "보낼 입력값을 아직 읽지 못합니다(전환 미완) — DEP_CD", unresolved: "query_param:DEP_CD" };
    const sbmOptions = {
        id: "tx_script_dts_dep",
        method: "post",
        action: "/CodeAction.do",
        ref: "dma_scriptDtsDepReq",
        target: "dtsDep=body.content",
        isProcessMsg: false,
        submitErrorHandler: (typeof scwin['dts_dep_onloaderror'] === 'function') ? scwin['dts_dep_onloaderror'] : (typeof scwin['dts_dep_onfail'] === 'function') ? scwin['dts_dep_onfail'] : undefined
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions);
        { const dsh = (typeof scwin['dts_dep_onloadcompleted'] === 'function') ? scwin['dts_dep_onloadcompleted'] : ((typeof scwin['dts_dep_onsuccess'] === 'function') ? scwin['dts_dep_onsuccess'] : null); if (dsh) { const dsl = $c.util.getComponent('dtsDep'); await dsh((dsl && dsl.getRowCount) ? dsl.getRowCount() : 0); } } }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldstf11100.tx_script_dts_dep" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};

/**
 * @method
 * @name tx_script_dts_DsclApprovalList
 * @description script dts Dscl Approval List 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_script_dts_DsclApprovalList = async function () {
    $c.util.getComponent("dma_scriptDts_DsclApprovalListReq").set("inputMessageId", "DSCLSTUDYCOND_AFF_IN");
    $c.util.getComponent("dma_scriptDts_DsclApprovalListReq").set("outputMessageId", "DSCLSTUDYLIST_AFF_OUT");
    $c.util.getComponent("dma_scriptDts_DsclApprovalListReq").set("SCREN_ID", 'ULDSTF11100.gfm');
    // as-is 가 URL 에 싣던 값을 정적으로 못 읽었다 — 빈 파라미터로 보내지 않는다.
    // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "보낼 입력값을 아직 읽지 못합니다(전환 미완) — ACPT_DATE, DEP_CD, EMP_NO, LD_MKT_TP, STAT_00, STAT_02, STAT_01, STAT_10, STAT_20, STAT_30, STAT_35, STAT_40, STAT_REG, AFF_STAT_00, AFF_STAT_01, AFF_STAT_10, AFF_STAT_20, AFF_STAT_30, AFF_STAT_40, UP_DEP_CD, SCREN_PROCES_TP_CD"
    throw { bizMessage: "보낼 입력값을 아직 읽지 못합니다(전환 미완) — ACPT_DATE, DEP_CD, EMP_NO, LD_MKT_TP, STAT_00, STAT_02, STAT_01, STAT_10, STAT_20, STAT_30, STAT_35, STAT_40, STAT_REG, AFF_STAT_00, AFF_STAT_01, AFF_STAT_10, AFF_STAT_20, AFF_STAT_30, AFF_STAT_40, UP_DEP_CD, SCREN_PROCES_TP_CD", unresolved: "query_param:ACPT_DATE,DEP_CD,EMP_NO,LD_MKT_TP,STAT_00,STAT_02,STAT_01,STAT_10,STAT_20,STAT_30,STAT_35,STAT_40,STAT_REG,AFF_STAT_00,AFF_STAT_01,AFF_STAT_10,AFF_STAT_20,AFF_STAT_30,AFF_STAT_40,UP_DEP_CD,SCREN_PROCES_TP_CD" };
    const sbmOptions = {
        id: "tx_script_dts_DsclApprovalList",
        method: "post",
        action: "/DisclosureStudyAffact.do",
        ref: "dma_scriptDts_DsclApprovalListReq",
        target: "dts_DsclApprovalList=body.content",
        isProcessMsg: false,
        submitErrorHandler: (typeof scwin['dts_DsclApprovalList_onloaderror'] === 'function') ? scwin['dts_DsclApprovalList_onloaderror'] : (typeof scwin['dts_DsclApprovalList_onfail'] === 'function') ? scwin['dts_DsclApprovalList_onfail'] : undefined
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions);
        { const dsh = (typeof scwin['dts_DsclApprovalList_onloadcompleted'] === 'function') ? scwin['dts_DsclApprovalList_onloadcompleted'] : ((typeof scwin['dts_DsclApprovalList_onsuccess'] === 'function') ? scwin['dts_DsclApprovalList_onsuccess'] : null); if (dsh) { const dsl = $c.util.getComponent('dts_DsclApprovalList'); await dsh((dsl && dsl.getRowCount) ? dsl.getRowCount() : 0); } } }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldstf11100.tx_script_dts_DsclApprovalList" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name depListLoadComplete
 * @description dep List Load Complete 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.depListLoadComplete = async function () {
    slc_cmb_TeamList.setValue($c.session.getUserInfo("depCd"));
    await scwin.initSearch();
};

/**
 * @method
 * @name initSearch
 * @description init Search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.initSearch = async function () {
    await scwin.reload('N');
};

/**
 * @method
 * @name reload
 * @description reload 처리
 * @param {*} pReload pReload
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.reload = async function (pReload) {
    await scwin.checkCond(pReload);
    setTimeout(async function(){ await scwin.reload('Y') }, 30000);
};

/**
 * @method
 * @name checkCond
 * @description check Cond 처리
 * @param {*} pReload pReload
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkCond = async function (pReload) {
    if (cal_edt_SrchDay.getValue().length < 8) {
        await $c.win.alert("일자 올바르게 입력하십시오.");
        $c.util.getComponent("cal_edt_SrchDay").focus();
        return;
    }
    let vStatCnt = 0;
    if (chk_chbStat00.checked === true) {
        vStatCnt++;
    }
    if (chk_chbStat02.checked === true) {
        vStatCnt++;
    }
    if (chk_chbStat01.checked === true) {
        vStatCnt++;
    }
    if (chk_chbStat10.checked === true) {
        vStatCnt++;
    }
    if (chk_chbStat20.checked === true) {
        vStatCnt++;
    }
    if (chk_chbStat30.checked === true) {
        vStatCnt++;
    }
    if (chk_chbStat35.checked === true) {
        vStatCnt++;
    }
    if (chk_chbStat40.checked === true) {
        vStatCnt++;
    }
    if (chk_chbReg.checked === true) {
        vStatCnt++;
    }
    let vAffStatCnt = 0;
    if (chk_chbAffstat00.checked === true) {
        vAffStatCnt++;
    }
    if (chk_chbAffstat01.checked === true) {
        vAffStatCnt++;
    }
    if (chk_chbAffstat10.checked === true) {
        vAffStatCnt++;
    }
    if (chk_chbAffstat20.checked === true) {
        vAffStatCnt++;
    }
    if (chk_chbAffstat30.checked === true) {
        vAffStatCnt++;
    }
    if (chk_chbAffstat40.checked === true) {
        vAffStatCnt++;
    }
    if (vStatCnt < 1 && vAffStatCnt < 1) {
        await $c.win.alert("처리현황 또는 사후심사현황을 한개 이상  선택하십시요.");
        return;
    }
    scwin.gDate = cal_edt_SrchDay.getValue();
    if ($c.session.getUserInfo("depCd").substring(0, 1) === '2' || $c.session.getUserInfo("depCd").substring(0, 2) === '34') {
        scwin.gDepCd = slc_cmb_TeamList.getValue();
        scwin.gEmpNo = slc_cmb_EmpList.getValue();
    } else {
        scwin.gDepCd = "";
        scwin.gEmpNo = "";
    }
    await scwin.search(pReload);
};

/**
 * @method
 * @name getChkValue
 * @description get Chk Value 처리
 * @param {Object} obj 컴포넌트
 * @returns {void}
 * @hidden N
 */
scwin.getChkValue = function (obj) {
    if (obj.checked === true) {
        return obj.value;
    } else {
        return "0";
    }
};

/**
 * @method
 * @name search
 * @description search 처리
 * @param {*} pReload pReload
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function (pReload) {
    ShowWin_yn(scwin.grd_Grid, scwin.search_yn);
    if ($c.session.getUserInfo("bondYn") === "Y") {
        scwin.gLdMktTp = "4";
    }
    let url = "/DisclosureStudyAffact.do?method=listDsclApprovAffact&inputMessageId=DSCLSTUDYCOND_AFF_IN" + "&outputMessageId=DSCLSTUDYLIST_AFF_OUT" + "&ACPT_DATE=" + scwin.gDate + "&DEP_CD=" + scwin.gDepCd + "&EMP_NO=" + scwin.gEmpNo + "&LD_MKT_TP=" + scwin.gLdMktTp + "&STAT_00=" + scwin.getChkValue(chk_chbStat00) + "&STAT_02=" + scwin.getChkValue(chk_chbStat02) + "&STAT_01=" + scwin.getChkValue(chk_chbStat01) + "&STAT_10=" + scwin.getChkValue(chk_chbStat10) + "&STAT_20=" + scwin.getChkValue(chk_chbStat20) + "&STAT_30=" + scwin.getChkValue(chk_chbStat30) + "&STAT_35=" + scwin.getChkValue(chk_chbStat35) + "&STAT_40=" + scwin.getChkValue(chk_chbStat40) + "&STAT_REG=" + scwin.getChkValue(chk_chbReg) + "&AFF_STAT_00=" + scwin.getChkValue(chk_chbAffstat00) + "&AFF_STAT_01=" + scwin.getChkValue(chk_chbAffstat01) + "&AFF_STAT_10=" + scwin.getChkValue(chk_chbAffstat10) + "&AFF_STAT_20=" + scwin.getChkValue(chk_chbAffstat20) + "&AFF_STAT_30=" + scwin.getChkValue(chk_chbAffstat30) + "&AFF_STAT_40=" + scwin.getChkValue(chk_chbAffstat40) + "&UP_DEP_CD=" + js_belngdepcd;
    if (pReload !== 'Y') {
        url = url + "&SCREN_ID=" + 'ULDSTF11100.gfm' + "&SCREN_PROCES_TP_CD=" + $c.fil.SCREN_PROCS_TP_CD_01;
    }

    await scwin.tx_script_dts_DsclApprovalList();
};

